GrammarTopic(slug="future",title="Future tense",level="A2",category="grammar",summary="Describe plans and predictions.",explanation="Future meaning is formed with forms of biti plus the l-participle.",examples=[GrammarExample(text="Jutri bom delal."),GrammarExample(text="Prišla bo zvečer.")]),
