GrammarTopic(slug="comparatives",title="Comparatives and superlatives",level="B1",category="grammar",summary="Compare people, objects and situations.",explanation="Use comparative and superlative adjective forms with appropriate agreement.",examples=[GrammarExample(text="Ta naloga je lažja."),GrammarExample(text="To je najboljša rešitev.")]),
GrammarTopic(slug="conditional",title="Conditional mood",level="B2",category="grammar",summary="Express hypotheses, wishes and polite proposals.",explanation="The conditional uses the particle bi together with the l-participle.",examples=[GrammarExample(text="Pomagal bi ti."),GrammarExample(text="Če bi imel čas, bi potoval.")]),
GrammarTopic(slug="relative",title="Relative clauses",level="B2",category="grammar",summary="Combine ideas into precise complex sentences.",explanation="Relative pronouns such as ki connect subordinate clauses and take their syntactic role within them.",examples=[GrammarExample(text="To je knjiga, ki sem jo včeraj kupil.")]),
GrammarTopic(slug="reported",title="Reported speech and discourse",level="C1",category="grammar",summary="Report information and organize complex discourse.",explanation="Use da and interrogative conjunctions to embed reported propositions while maintaining clear reference.",examples=[GrammarExample(text="Rekel je, da bo prišel jutri.")]),
GrammarTopic(slug="register",title="Formal and professional register",level="C1",category="style",summary="Adapt Slovenian to institutional and professional contexts.",explanation="Formal Slovenian favors precise terminology, conventional requests and explicit logical connectors.",examples=[GrammarExample(text="Prosimo, da predložite zahtevano dokumentacijo.")]),
GrammarTopic(slug="nominalization",title="Academic nominalization and complex syntax",level="C2",category="style",summary="Process dense analytical and academic Slovenian.",explanation="Advanced Slovenian uses nominalizations, participial structures and layered subordination to compress complex arguments.",examples=[GrammarExample(text="Izvedba ukrepa zahteva predhodno presojo njegovih učinkov.")]),
GrammarTopic(slug="pragmatics",title="Idiomatic and pragmatic nuance",level="C2",category="pragmatics",summary="Interpret implication, tone and idiomatic meaning.",explanation="Near-native proficiency includes collocations, discourse stance, understatement and context-sensitive expressions.",examples=[GrammarExample(text="Ni vse črno-belo.")])
